INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l38','make sure','',NULL,'/meɪk ʃʊr/','Make sure the bottle is clean and dry.','务必确保瓶子干净干燥。','Make sure you boil the water.','一定要把水烧开。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l38','rely on','',NULL,'/rɪˈlaɪ ɑːn/','Do not rely on alcohol to sterilize water.','别指望用酒精给水灭菌。','You can rely on boiled water.','你可以放心用烧开的水。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l38','beware of','',NULL,'/bɪˈwer ʌv/','Beware of untreated tap-water.','当心未处理的自来水。','Beware of the dog.','当心恶犬。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l38','on request','',NULL,'/ɑːn rɪˈkwest/','Some hotels supply boiled water on request.','有些旅馆应客人要求供应开水。','Copies are available on request.','如有需要可索取副本。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp1','choice','{"stem":"\"Contamination of water is usually ___ to poor sanitation.\"(‘由于/归因于’= be __ to,填那个形容词)","options":["thanks","owed","due","because"],"answer_index":2,"stem_cn":"水污染通常是由差劲的卫生条件造成的。","explanation_cn":"‘由于/归因于’= be due to;填形容词 due。✓ is due to poor sanitation. ✗ owed / thanks / because:此结构用 due。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp1','choice','{"stem":"\"The outbreak was ___ to sewage leaking into the wells.\"(‘…所致’= be __ to,填那个形容词)","options":["due","because","since","thanks"],"answer_index":0,"stem_cn":"这场疫情是污水渗入水井所致。","explanation_cn":"‘…所致’= be due to;填 due。✓ was due to sewage leaking into the wells. ✗ because / since / thanks:此结构用 due。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp1','choice','{"stem":"\"Many illnesses are due ___ unsafe drinking water.\"(be due __,‘由于’,填 due 后那个介词)","options":["with","of","to","for"],"answer_index":2,"stem_cn":"许多疾病是不安全的饮用水引起的。","explanation_cn":"be due + 介词;due 后接 to。✓ are due to unsafe drinking water. ✗ of / for / with:due 搭配 to。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp2','choice','{"stem":"\"___ a piped supply is safe at its source, it may be unsafe at the tap.\"(‘即使’,让步连词)","options":["So that","Even if","Because","Unless"],"answer_index":1,"stem_cn":"即使管道水在水源处安全,到水龙头时也可能不安全。","explanation_cn":"‘即使…’的让步连词是 Even if。✓ Even if a piped supply is safe … ✗ Because / Unless / So that:‘即使’用 Even if。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp2','choice','{"stem":"\"___ the water looks clean, it may still be contaminated.\"(‘即使’,让步连词)","options":["Unless","Because","So","Even if"],"answer_index":3,"stem_cn":"即使水看起来干净,也可能已被污染。","explanation_cn":"‘即使…’用 Even if。✓ Even if the water looks clean … ✗ Because / So / Unless:‘即使’用 Even if。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp2','choice','{"stem":"\"Boil the water even ___ you are in a hurry.\"(‘即使’,even __ 结构,填 even 后那个词)","options":["though","if","so","that"],"answer_index":1,"stem_cn":"即使你赶时间,也要把水烧开。","explanation_cn":"even if 结构,even 后接 if。✓ even if you are in a hurry. ✗ though / that / so:even 后用 if。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp3','choice','{"stem":"\"Ice is only ___ safe as the water from which it is made.\"(‘和…一样…’的同级比较,填这个结构开头的那个词)","options":["as","more","than","so"],"answer_index":0,"stem_cn":"冰只和造它的水一样安全。","explanation_cn":"‘和…一样安全’= as safe as;填与后面 as 呼应的第一个 as。✓ as safe as the water. ✗ so / than / more:肯定同级比较用 as … as。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp3','choice','{"stem":"\"Bottled water is not ___ risky as untreated tap-water.\"(‘不像…那么…’= not __ … as,填与后面 as 呼应的那个词)","options":["more","than","so","as"],"answer_index":2,"stem_cn":"瓶装水不像未处理的自来水那么有风险。","explanation_cn":"‘不像…那么…’= not so … as;填第一个词 so。✓ not so risky as untreated tap-water. ✗ as / more / than:否定可用 not so … as。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp3','choice','{"stem":"\"Boiled water is just as ___ as fresh spring water.\"(as + 形容词 + as,填形容词)","options":["safe","safest","safer","safely"],"answer_index":0,"stem_cn":"烧开的水和新鲜泉水一样安全。","explanation_cn":"as + 形容词 + as,填形容词原级 safe。✓ just as safe as fresh spring water. ✗ safer(比较级)/ safest(最高级)/ safely(副词):as … as 中间用原级。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp4','choice','{"stem":"\"___ sure that all bottles are opened in your presence.\"(祈使句,‘务必确保’,填动词原形)","options":["Made","To make","Make","Making"],"answer_index":2,"stem_cn":"务必确保所有瓶子当着你的面打开。","explanation_cn":"祈使句用动词原形开头;‘务必确保’用 Make(sure)。✓ Make sure that all bottles are opened … ✗ Making / Made / To make:祈使句用动词原形。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp4','choice','{"stem":"\"___ politely any cold drink from an unknown source.\"(祈使句,‘婉拒’,填动词原形)","options":["Refused","To refuse","Refusing","Refuse"],"answer_index":3,"stem_cn":"婉拒任何来源不明的冷饮。","explanation_cn":"祈使句用动词原形开头;‘婉拒’用 Refuse。✓ Refuse politely any cold drink … ✗ Refusing / Refused / To refuse:祈使句用动词原形。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp4','choice','{"stem":"\"___ of methylated alcohol, which is very poisonous.\"(祈使句,‘当心’,填动词原形)","options":["Bewared","Bewaring","Beware","To beware"],"answer_index":2,"stem_cn":"当心工业变性酒精,它毒性很强。","explanation_cn":"祈使句用动词原形开头;‘当心’用 Beware(of)。✓ Beware of methylated alcohol … ✗ Bewaring / Bewared / To beware:祈使句用动词原形。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp5','choice','{"stem":"\"The water ___ which the ice is made must be safe.\"(介词+关系代词;‘用…制成’,填与 make 搭配表‘用…’的那个介词)","options":["from","of","at","by"],"answer_index":0,"stem_cn":"用来制冰的水必须是安全的。","explanation_cn":"介词 + 关系代词;‘用…制成’是 make from,介词用 from。✓ the water from which the ice is made. ✗ of / at / by:make 搭配 from。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp5','choice','{"stem":"\"The source ___ which the disease spread was the well.\"(介词+关系代词;‘从…扩散’,填与 spread 搭配的那个介词)","options":["in","from","of","at"],"answer_index":1,"stem_cn":"疾病扩散的源头是那口井。","explanation_cn":"介词 + 关系代词;‘从…扩散’是 spread from,介词用 from。✓ the source from which the disease spread. ✗ of / at / in:spread 搭配 from。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp5','choice','{"stem":"\"The bottle ___ which you drink should be clean.\"(介词+关系代词;‘从其中饮用’,填与 drink 搭配的那个介词)","options":["at","on","from","of"],"answer_index":2,"stem_cn":"你所饮用的那只瓶子应当是干净的。","explanation_cn":"介词 + 关系代词;‘从其中饮用’是 drink from,介词用 from。✓ the bottle from which you drink. ✗ of / at / on:drink 搭配 from。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp6','choice','{"stem":"\"The presence of harmful or dirty substances in water is ___.\"(“污染”用哪个词)","options":["contamination","conversation","cooperation","celebration"],"answer_index":0,"stem_cn":"水中存在有害或肮脏物质。","explanation_cn":"水中存在有害或肮脏物质是 contamination(污染)。✓ the presence of harmful substances is contamination. ✗ celebration 庆祝;✗ cooperation 合作;✗ conversation 交谈——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp6','choice','{"stem":"\"A substance used to destroy harmful germs is a ___.\"(“消毒剂”用哪个词)","options":["ingredient","instrument","disinfectant","apartment"],"answer_index":2,"stem_cn":"用来杀灭有害病菌的物质。","explanation_cn":"用来杀灭有害病菌的物质是 disinfectant(消毒剂)。✓ a substance to destroy germs is a disinfectant. ✗ ingredient 原料;✗ instrument 器械;✗ apartment 公寓——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',5,'am4_l38_gp6','choice','{"stem":"\"To make something free from germs is to ___ it.\"(“消毒,灭菌”用哪个词)","options":["sterilize","memorize","organize","apologize"],"answer_index":0,"stem_cn":"使某物无菌。","explanation_cn":"使某物无菌是 sterilize(消毒、灭菌)。✓ to make something free from germs is to sterilize. ✗ memorize 记住;✗ apologize 道歉;✗ organize 组织——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',6,NULL,'choice','{"stem":"contamination 的意思是:","options":["污染","凝结","蒸发","净化"],"answer_index":0,"explanation_cn":"contamination = 污染。✓ contamination of a water supply."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',6,NULL,'choice','{"stem":"sanitation 的意思是:","options":["教育","卫生设施,环境卫生","娱乐","交通"],"answer_index":1,"explanation_cn":"sanitation = 卫生设施、环境卫生。✓ due to poor sanitation."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',6,NULL,'choice','{"stem":"sewage 的意思是:","options":["泉水","海水","雨水","污水,下水道污物"],"answer_index":3,"explanation_cn":"sewage = 污水、下水道污物。✓ sewage seeping into the source."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',6,NULL,'choice','{"stem":"intermittent 的意思是:","options":["永久的","间歇的,断断续续的","持续的","迅速的"],"answer_index":1,"explanation_cn":"intermittent = 间歇的、断断续续的。✓ an intermittent supply is suspect."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',6,NULL,'choice','{"stem":"sterilize 的意思是:","options":["冷冻","加热","污染","消毒,灭菌"],"answer_index":3,"explanation_cn":"sterilize = 消毒、灭菌。✓ should not be relied upon to sterilize water."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',6,NULL,'choice','{"stem":"acidic 的意思是:","options":["碱性的","中性的","酸性的","甜的"],"answer_index":2,"explanation_cn":"acidic = 酸性的。✓ carbonated drinks are slightly acidic."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',7,NULL,'cloze','{"stem":"第 1 空","context":"Contamination of water is usually ___1___ to poor sanitation. ___2___ a piped supply is safe at its source, it may be unsafe at the tap. Ice is only ___3___ safe as the water from which it is made. ___4___ sure that every bottle is opened in your presence.","blank_no":1,"options":["due","because","since","thanks"],"answer_index":0,"explanation_cn":"‘由于/归因于’= be due to;填 due。✓ is due to poor sanitation."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',7,NULL,'cloze','{"stem":"第 2 空","context":"Contamination of water is usually ___1___ to poor sanitation. ___2___ a piped supply is safe at its source, it may be unsafe at the tap. Ice is only ___3___ safe as the water from which it is made. ___4___ sure that every bottle is opened in your presence.","blank_no":2,"options":["Even if","Because","Unless","So"],"answer_index":0,"explanation_cn":"‘即使…’的让步连词是 Even if。✓ Even if a piped supply is safe at its source …"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',7,NULL,'cloze','{"stem":"第 3 空","context":"Contamination of water is usually ___1___ to poor sanitation. ___2___ a piped supply is safe at its source, it may be unsafe at the tap. Ice is only ___3___ safe as the water from which it is made. ___4___ sure that every bottle is opened in your presence.","blank_no":3,"options":["as","so","than","more"],"answer_index":0,"explanation_cn":"‘和…一样安全’= as safe as;填第一个 as。✓ as safe as the water from which it is made."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',7,NULL,'cloze','{"stem":"第 4 空","context":"Contamination of water is usually ___1___ to poor sanitation. ___2___ a piped supply is safe at its source, it may be unsafe at the tap. Ice is only ___3___ safe as the water from which it is made. ___4___ sure that every bottle is opened in your presence.","blank_no":4,"options":["Make","Making","Made","To make"],"answer_index":0,"explanation_cn":"祈使句用动词原形开头,‘务必确保’用 Make。✓ Make sure that every bottle is opened …"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',8,NULL,'choice','{"stem":"What does this text mainly describe?","options":["How rivers become polluted over time","How to build a water pipeline","The history of bottled drinks","How travelers can keep their drinking water safe"],"answer_index":3,"explanation_cn":"录音说:本文讲的是旅行者如何确保饮用水安全。✓ keeping drinking water safe."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',8,NULL,'choice','{"stem":"Why may piped water be unsafe even if it is safe at its source?","options":["It can be contaminated on the way to the tap, by leaking sewage or waste","Source water is never safe","The pipes add minerals","It is always boiled first"],"answer_index":0,"explanation_cn":"录音说:即使水源安全,水在流向龙头途中也可能因污水渗漏或废物而受污染。✓ contaminated on the way."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',8,NULL,'choice','{"stem":"What is always a good way of treating water, according to the text?","options":["Adding alcohol to it","Shaking it hard","Boiling it","Freezing it"],"answer_index":2,"explanation_cn":"录音说:烧开始终是处理水、使之安全的好办法。✓ boiling is a good way."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',9,NULL,'choice','{"stem":"你想说\"水污染通常是由差劲的卫生条件造成的\"(be due to):","options":["Contamination of water is usually due of poor sanitation.","Contamination of water is usually due to poor sanitation.","Contamination of water is usually due poor sanitation.","Contamination of water is usually owing poor sanitation."],"answer_index":1,"explanation_cn":"be due to + 名词,‘由于’;due 后接 to(不写 due poor、不写 due of)、也不用 owing 少 to。✓ due to poor sanitation. 场合:说“…是由…造成的”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',9,NULL,'choice','{"stem":"你想说\"即使管道水在水源处是安全的,到水龙头时也可能不安全\"(Even if 让步):","options":["Even though if a piped supply is safe at its source, it may be unsafe at the tap.","Even if a piped supply is safe at its source, but it may be unsafe at the tap.","Even a piped supply is safe at its source, it may be unsafe at the tap.","Even if a piped supply is safe at its source, it may be unsafe at the tap."],"answer_index":3,"explanation_cn":"Even if 引导让步,‘即使’;不能省 if(不写 Even a piped…)、主句不再加 but(不写 Even if…, but…)、也不写 Even though if。✓ Even if …, … 场合:说“即使…也…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',9,NULL,'choice','{"stem":"你想说\"冰只和造它的水一样安全\"(as … as):","options":["Ice is only as safe as the water from which it is made.","Ice is only so safe as the water from which it is made.","Ice is only as safe than the water from which it is made.","Ice is only as safe as the water from which it is make."],"answer_index":0,"explanation_cn":"as … as 同级比较;两个都用 as(不写 as … than)、肯定句不用 so … as、从句 it is made 用被动(不写 it is make)。✓ as safe as … 场合:说“和…一样…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"contamination 的意思是:","options":["蒸发","污染","凝结","净化"],"answer_index":1,"explanation_cn":"contamination = 污染。✓ contamination of a water supply."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"sterilize 的意思是:","options":["冷冻","污染","消毒,灭菌","加热"],"answer_index":2,"explanation_cn":"sterilize = 消毒、灭菌。✓ should not be relied upon to sterilize water."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"\"Contamination of water is usually ___ to poor sanitation.\"(‘由于/归因于’= be __ to,填那个词)","options":["due","thanks","because","since"],"answer_index":0,"stem_cn":"水污染通常由差劲的卫生条件造成。","explanation_cn":"‘由于/归因于’= be due to;填 due。✓ due to poor sanitation. ✗ because / since / thanks。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"\"___ a piped supply is safe at its source, it may be unsafe at the tap.\"(‘即使’,让步连词)","options":["Unless","Because","So","Even if"],"answer_index":3,"stem_cn":"即使管道水在水源处安全,到水龙头时也可能不安全。","explanation_cn":"‘即使…’的让步连词是 Even if。✓ Even if a piped supply is safe … ✗ Because / Unless / So。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"\"make sure\" 的意思是:","options":["拒绝","确保,查明","忘记","怀疑"],"answer_index":1,"explanation_cn":"make sure = 确保、查明。✓ make sure the bottle is clean."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"\"beware of\" 的意思是:","options":["忽视","喜爱","当心,提防","接受"],"answer_index":2,"explanation_cn":"beware of = 当心、提防。✓ beware of untreated tap-water."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"According to the text, why should intermittent tap-water supplies be treated as especially suspect?","options":["They are always cold","The on-and-off flow makes contamination more likely","They taste bad","They cost more"],"answer_index":1,"passage":"Contamination of a water supply is usually due to poor sanitation near the water source, to sewage seeping into the source itself, to leakage of sewage within the distribution system, or to pollution by industrial and farm waste. Even if a piped supply is safe where it begins, it is not always safe by the time it reaches the tap; and an intermittent, on-and-off supply should be treated as especially suspect. Travelers on short trips to places where the water is of uncertain quality should avoid drinking tap-water, or any untreated water from another source. It is best to keep to hot drinks, or to bottled or canned drinks of well-known brands, since international standards of treatment are usually followed at the bottling plants. Carbonated drinks are slightly acidic, and therefore a little safer. Make sure that every bottle is opened in your presence, and that its rim is clean and dry. Boiling is always a good way of treating water. Some hotels will supply boiled water on request, and this can be used for drinking or for brushing the teeth. A portable heating element that can boil a small quantity of water is useful wherever the right voltage of electricity is available. Refuse politely any cold drink from an unknown source, and remember that ice is only as safe as the water from which it is made; ice should never be put in a drink unless the water is known to be safe. A drink is far better cooled by standing the container on ice than by dropping ice into it. Alcohol may serve as a disinfectant, but it should not be relied upon to sterilize drinking water. As a bactericidal agent, ethanol works best at a concentration of about fifty to seventy per cent; below twenty per cent its action is negligible. Beware, above all, of methylated alcohol, which is highly poisonous and must never be added to water meant for drinking.","explanation_cn":"课文说:时有时无的供水更易被污染,故格外可疑。✓ intermittent supply suspect."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"What does the text advise travelers to drink in areas with unsafe water?","options":["Hot drinks, or bottled or canned drinks of well-known brands","Any cold drink offered to them","Untreated tap-water","Water straight from a river"],"answer_index":0,"passage":"Contamination of a water supply is usually due to poor sanitation near the water source, to sewage seeping into the source itself, to leakage of sewage within the distribution system, or to pollution by industrial and farm waste. Even if a piped supply is safe where it begins, it is not always safe by the time it reaches the tap; and an intermittent, on-and-off supply should be treated as especially suspect. Travelers on short trips to places where the water is of uncertain quality should avoid drinking tap-water, or any untreated water from another source. It is best to keep to hot drinks, or to bottled or canned drinks of well-known brands, since international standards of treatment are usually followed at the bottling plants. Carbonated drinks are slightly acidic, and therefore a little safer. Make sure that every bottle is opened in your presence, and that its rim is clean and dry. Boiling is always a good way of treating water. Some hotels will supply boiled water on request, and this can be used for drinking or for brushing the teeth. A portable heating element that can boil a small quantity of water is useful wherever the right voltage of electricity is available. Refuse politely any cold drink from an unknown source, and remember that ice is only as safe as the water from which it is made; ice should never be put in a drink unless the water is known to be safe. A drink is far better cooled by standing the container on ice than by dropping ice into it. Alcohol may serve as a disinfectant, but it should not be relied upon to sterilize drinking water. As a bactericidal agent, ethanol works best at a concentration of about fifty to seventy per cent; below twenty per cent its action is negligible. Beware, above all, of methylated alcohol, which is highly poisonous and must never be added to water meant for drinking.","explanation_cn":"课文说:水质不明之地,旅行者应喝热饮或知名品牌瓶装/罐装饮料。✓ hot drinks, bottled brands."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"Why is ice a possible danger?","options":["It is always dirty","It is only as safe as the water it is made from","It is made of sewage","It cools drinks too much"],"answer_index":1,"audio":"Contamination of a water supply is usually due to poor sanitation near the water source, to sewage seeping into the source itself, to leakage of sewage within the distribution system, or to pollution by industrial and farm waste. Even if a piped supply is safe where it begins, it is not always safe by the time it reaches the tap; and an intermittent, on-and-off supply should be treated as especially suspect. Travelers on short trips to places where the water is of uncertain quality should avoid drinking tap-water, or any untreated water from another source. It is best to keep to hot drinks, or to bottled or canned drinks of well-known brands, since international standards of treatment are usually followed at the bottling plants. Carbonated drinks are slightly acidic, and therefore a little safer. Make sure that every bottle is opened in your presence, and that its rim is clean and dry. Boiling is always a good way of treating water. Some hotels will supply boiled water on request, and this can be used for drinking or for brushing the teeth. A portable heating element that can boil a small quantity of water is useful wherever the right voltage of electricity is available. Refuse politely any cold drink from an unknown source, and remember that ice is only as safe as the water from which it is made; ice should never be put in a drink unless the water is known to be safe. A drink is far better cooled by standing the container on ice than by dropping ice into it. Alcohol may serve as a disinfectant, but it should not be relied upon to sterilize drinking water. As a bactericidal agent, ethanol works best at a concentration of about fifty to seventy per cent; below twenty per cent its action is negligible. Beware, above all, of methylated alcohol, which is highly poisonous and must never be added to water meant for drinking.","explanation_cn":"课文说:冰只和造它的水一样安全,故来源不明的冰有危险。✓ ice as safe as its water."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l38',10,NULL,'choice','{"stem":"According to the text, how safe is alcohol for sterilizing drinking water?","options":["It is the best sterilizer","It always makes water safe","It is completely harmless in any form","It should not be relied upon to sterilize water"],"answer_index":3,"audio":"Contamination of a water supply is usually due to poor sanitation near the water source, to sewage seeping into the source itself, to leakage of sewage within the distribution system, or to pollution by industrial and farm waste. Even if a piped supply is safe where it begins, it is not always safe by the time it reaches the tap; and an intermittent, on-and-off supply should be treated as especially suspect. Travelers on short trips to places where the water is of uncertain quality should avoid drinking tap-water, or any untreated water from another source. It is best to keep to hot drinks, or to bottled or canned drinks of well-known brands, since international standards of treatment are usually followed at the bottling plants. Carbonated drinks are slightly acidic, and therefore a little safer. Make sure that every bottle is opened in your presence, and that its rim is clean and dry. Boiling is always a good way of treating water. Some hotels will supply boiled water on request, and this can be used for drinking or for brushing the teeth. A portable heating element that can boil a small quantity of water is useful wherever the right voltage of electricity is available. Refuse politely any cold drink from an unknown source, and remember that ice is only as safe as the water from which it is made; ice should never be put in a drink unless the water is known to be safe. A drink is far better cooled by standing the container on ice than by dropping ice into it. Alcohol may serve as a disinfectant, but it should not be relied upon to sterilize drinking water. As a bactericidal agent, ethanol works best at a concentration of about fifty to seventy per cent; below twenty per cent its action is negligible. Beware, above all, of methylated alcohol, which is highly poisonous and must never be added to water meant for drinking.","explanation_cn":"课文说:酒精虽可作消毒剂,却不应被指望用来给饮用水灭菌。✓ not relied upon to sterilize."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
